import * as D from './domain-27ca4e179461.mjs';
import {savePhase,setHabitCheck,habitSummary} from './rebuild-model-27ca4e179461.mjs';
import {setTaskSources,setPhaseArchived,phaseSlices} from './stage-model-27ca4e179461.mjs';
import {skillAt} from './growth-model-27ca4e179461.mjs';
import {e,duration,num} from './views-27ca4e179461.mjs';
import {button} from './rebuild-views-27ca4e179461.mjs';
export function createStageUI({getState,getUI,tasks,save,render,navigate,openModal,closeModal,entityReplace,toast}){
 async function phase(id=null,{onReturn=null}={}){const state=getState(),old=state.phases.find(p=>p.id===id),today=D.dateKey(Date.now(),state.timeZone),p=old??{id:D.uid(),title:'',startDate:today,endDate:D.addDays(today,6),skillIds:[],note:'',archived:false};await tasks.open({id:'phase:'+(id??'new'),kind:'phase',onReturn,title:old?'编辑阶段':'新阶段',original:old,initial:p,extra:{entityId:p.id},body:()=>`<label>阶段名称<input name="title" maxlength="100" required placeholder="这段时间的方向"></label><div class="form-row"><label>开始<input type="date" name="startDate" required></label><label>结束<input type="date" name="endDate" required></label></div><label>想留下什么<textarea name="note" maxlength="20000"></textarea></label><details><summary>整体培养方向 · 可选</summary><div class="checkbox-list" data-choice-label="整体培养方向">${state.skills.filter(k=>k.status!=='archived'||p.skillIds.includes(k.id)).map(k=>`<label class="check"><input type="checkbox" name="skillIds" value="${e(k.id)}">${e(k.name)}</label>`).join('')}</div></details>${old?'<p class="quiet-note">日期调整会重算该阶段任务的范围，生活记录保留。</p>':''}`,onSave:async(f,{commit,original,payload})=>{const a=f.get('startDate'),b=f.get('endDate');if(!D.isDate(a)||!D.isDate(b)||b<a||D.addDays(a,365)<b)throw Error('阶段最多366天，请核对起止日期');await commit(s=>{const current=s.phases.find(x=>x.id===payload.entityId);if(original&&JSON.stringify(current)!==JSON.stringify(original))throw Error('阶段已变化，请读取最新配置');return savePhase(s,{...p,id:payload.entityId,title:f.get('title'),startDate:a,endDate:b,note:f.get('note'),skillIds:f.getAll('skillIds')});});},onSaved:onReturn??(payload=>navigate('phaseDetail',{phaseId:payload.entityId}))});}
 async function task(id=null,phaseId=null){const state=getState(),old=state.plans.find(p=>p.id===id),parent=state.phases.find(p=>p.id===(old?.phaseId??phaseId));if(!parent)throw Error('请先创建一个阶段');const t=old??{id:D.uid(),phaseId:parent.id,title:'',startDate:parent.startDate,endDate:parent.endDate,targetMinutes:0,outcome:'',activityIds:[],skillIds:[],groupIds:[],completedAt:null,focus:false},mode=t.targetMinutes?t.outcome?'both':'time':'outcome';await tasks.open({id:'plan:'+(id??'new:'+parent.id),kind:'plan',title:old?'编辑任务':'添加任务',original:old,initial:{...t,mode:old?mode:'time',targetMinutes:t.targetMinutes||''},extra:{entityId:t.id},body:()=>`<p class="r-date">${e(parent.title)}</p><label>任务名称<input name="title" maxlength="100" required></label><label>跟踪方式<select name="mode"><option value="time">时间投入</option><option value="outcome">手动成果</option><option value="both">时间与成果</option></select></label><label data-time-fields>目标分钟<input name="targetMinutes" type="number" min="1" max="10000000" step="1"></label><label data-outcome-fields>成果要求<textarea name="outcome" maxlength="20000"></textarea></label><fieldset><legend>固定计时标签</legend><div class="checkbox-list">${state.activities.filter(a=>(a.groupId==='category-phase'&&!a.archived)||t.activityIds.includes(a.id)).map(a=>`<label class="check"><input type="checkbox" name="activityIds" value="${e(a.id)}">${e(a.name)}${a.archived?' · 归档':''}</label>`).join('')}</div><label>或新建阶段标签<input name="newLabel" maxlength="60" placeholder="如：课程项目"></label></fieldset>${old?.groupIds?.length||old?.skillIds.length?'<label class="check"><input type="checkbox" name="keepLegacy" checked>保留旧类别／培养来源规则</label>':''}<p class="quiet-note">标签关联从保存时生效。成果与能力判断分别保留。</p>`,bind(form){const sync=()=>{const mode=form.elements.mode.value;for(const [selector,hide,name]of [['[data-time-fields]',mode==='outcome','targetMinutes'],['[data-outcome-fields]',mode==='time','outcome']]){form.querySelector(selector).hidden=hide;form.elements[name].disabled=hide;form.elements[name].required=!hide;}};form.elements.mode.onchange=sync;sync();},onSave:async(f,{commit,original,payload})=>{const mode=f.get('mode'),target=mode==='outcome'?0:Number(f.get('targetMinutes')),outcome=mode==='time'?'':String(f.get('outcome')??'').trim();if(mode!=='outcome'&&(!Number.isInteger(target)||target<=0))throw Error('时间目标需正整数分钟');if(mode!=='time'&&!outcome)throw Error('请写下成果要求');if(original?.completedAt&&outcome!==original.outcome)throw Error('先更正已完成的成果状态，再修改要求');await commit(s=>{let ids=f.getAll('activityIds');const name=String(f.get('newLabel')??'').trim();if(name){const group=s.activityGroups.find(g=>g.id==='category-phase'),a={id:D.uid(),groupId:group.id,category:group.name,name,color:group.color,mainSkillId:null,relatedSkillIds:[],growthMode:'none',phoneMode:'parallel',favorite:false,mainline:false,archived:false};s.activities.push(a);ids.push(a.id);}if(target&&!ids.length&&!f.has('keepLegacy'))throw Error('选择一个标签或创建阶段标签，即可自动带入时间');const next={...t,id:payload.entityId,title:String(f.get('title')).trim(),targetMinutes:target,outcome};s=entityReplace(s,'plans',original,next);if(!original||JSON.stringify(ids.slice().sort())!==JSON.stringify(original.activityIds.slice().sort())||(!f.has('keepLegacy')&&(original.groupIds?.length||original.skillIds.length)))s=setTaskSources(s,next.id,ids,{preserveLegacy:f.has('keepLegacy')});return s;});},onSaved:payload=>navigate('taskDetail',{taskId:payload.entityId})});}
 async function habit(id=null){const s=getState(),old=s.habits.find(h=>h.id===id),h=old??{id:D.uid(),title:'',archived:false,startDate:D.dateKey(Date.now(),s.timeZone),timeZone:s.timeZone,createdAt:Date.now()};await tasks.open({id:'habit:'+(id??'new'),kind:'habit',title:old?'编辑习惯':'每日习惯',original:old,initial:{...h,archived:h.archived?['on']:[]},extra:{entityId:h.id},body:()=>`<label>习惯名称<input name="title" maxlength="100" required placeholder="如：睡前阅读"></label>${old?'<label class="check"><input type="checkbox" name="archived">归档收起，历史保留</label>':''}<p class="quiet-note">每天轻点一次，可撤销。习惯独立延续，不自动增加时间或成长。</p>`,onSave:async(f,{commit,original,payload})=>{await commit(s=>entityReplace(s,'habits',original,{...h,id:payload.entityId,title:String(f.get('title')).trim(),archived:f.has('archived')}));toast('习惯已保存');}});}
 function habitHistory(id,month=null){const s=getState(),h=s.habits.find(h=>h.id===id),today=D.dateKey(Date.now(),h.timeZone??s.timeZone),m=month??getUI().habitMonth??today.slice(0,7),start=m+'-01',v=habitSummary(s,id,today),days=[];if(!D.isDate(start))throw Error('月份无效');for(let d=start;d.slice(0,7)===m;d=D.addDays(d,1))days.push(d);openModal(h.title,`<div class="r-heading"><p>累计 ${v.total} 天 · 连续 ${v.current} 天 · 最长 ${v.best} 天</p><input type="month" id="habit-month" value="${m}" aria-label="打卡月份"></div><div class="r-habit-grid">${days.map(d=>button('check-habit',d.slice(-2),id,'r-check',`data-date="${d}" data-checked="${!v.dates.has(d)}" data-history="true" aria-label="${d} ${v.dates.has(d)?'已打卡，点按撤销':'未打卡'}" aria-pressed="${v.dates.has(d)}" ${d>today||d<h.startDate||h.archived?'disabled':''}`)).join('')}</div>${button('edit-habit','编辑或归档',id,'text-button')}`);document.querySelector('#habit-month').onchange=event=>{getUI().habitMonth=event.target.value;habitHistory(id,event.target.value);};}
 return {editPhase:phase,actions:{'new-phase':()=>phase(),'edit-phase':phase,'phase-detail':id=>navigate('phaseDetail',{phaseId:id}),'new-task':id=>task(null,id),'edit-task':id=>task(id),'task-detail':id=>navigate('taskDetail',{taskId:id}),'toggle-phase-archive':()=>{getUI().archivedPhases=!getUI().archivedPhases;render();},'archive-phase':async id=>{await save(s=>setPhaseArchived(s,id,!s.phases.find(p=>p.id===id).archived));toast('阶段状态已更新，历史保留');},'archive-task':async id=>{await save(s=>{const p=s.plans.find(p=>p.id===id);return setTaskSources(s,id,p.activityIds,{active:!!p.archived,preserveLegacy:true});});toast('任务状态已更新');},'new-habit':()=>habit(),'edit-habit':habit,'habit-history':id=>habitHistory(id),'toggle-habit-archive':()=>{getUI().archivedHabits=!getUI().archivedHabits;render();},'check-habit':async(id,el)=>{el.disabled=true;try{await save(s=>setHabitCheck(s,id,el.dataset.date,el.dataset.checked==='true'));if(el.dataset.history)habitHistory(id);}finally{if(el.isConnected)el.disabled=false;}},'phase-growth':id=>{const s=getState(),p=s.phases.find(p=>p.id===id),rows=phaseSlices(s,id,D.confirmedSessions(s)),from=D.dayStart(p.startDate,s.timeZone),until=Math.min(Date.now(),D.dayStart(D.addDays(p.endDate,1),s.timeZone)),ids=new Set([...p.skillIds,...rows.flatMap(r=>[r.mainSkillId,...r.relatedSkillIds]).filter(Boolean)]);openModal('期初与期内培养',`<p>${e(p.title)} · ${p.startDate} — ${p.endDate}</p>${[...ids].map(id=>{const skill=s.skills.find(k=>k.id===id),a=skillAt(s,id,Math.min(from,Date.now())),b=skillAt(s,id,until);return `<section class="r-section"><h3>${e(skill.name)}</h3><p>期初 ${a.located?num(a.growthPoints):'尚未定位'} · 期末/当前 ${b.located?num(b.growthPoints):'尚未定位'} 分</p><p>阶段去重实录 ${num(D.contribution(rows)[id]?.toNumber()??0)} 分</p>${button('skill','查看来源与当前自评',id,'text-button')}</section>`;}).join('')||'<p>尚无培养来源。</p>'}`);}}};
}
